// supabase/functions/orbit-worker/handlers/source.ts
function sourceSearch(config) {
  return async (job, ctx) => {
    if (!job.userId) throw new Error("source.search needs a user");
    const s = makeServices(config, { db: ctx.db, now: ctx.now, queue: ctx.queue });
    try {
      await runSourcing(s, job.userId, job.payload);
    } catch (e) {
      if (e instanceof HttpError && e.status < 500) return;
      throw e;
    }
  };
}

// supabase/functions/orbit-worker/handlers/voice.ts
function voiceHandlers(config) {
  return {
    "voice.embed_sent": async (job, ctx) => {
      if (!job.userId) throw new JobSkipped("no_user");
      const s = makeServices(config, { db: ctx.db, now: ctx.now, queue: ctx.queue });
      const asked = Number(job.payload.limit);
      const limit2 = Number.isInteger(asked) && asked > 0 ? Math.min(asked, EMBED_SENT_LIMIT) : EMBED_SENT_LIMIT;
      await embedSent(ctx.db, s.embed, job.userId, limit2);
    },
    "voice.card": async (job, ctx) => {
      if (!job.userId) throw new JobSkipped("no_user");
      await relearnCard(ctx.db, job.userId, ctx.now());
    },
    "voice.distill": async (job, ctx) => {
      if (!job.userId) throw new JobSkipped("no_user");
      const relearn = job.payload.reason === "relearn";
      await distillVoice(makeServices(config, { db: ctx.db, now: ctx.now, queue: ctx.queue }), job.userId, {
        full: relearn,
        batch: !relearn
      });
    }
  };
}

// supabase/functions/orbit-worker/handlers/agents.ts
function agentHandlers(config = { env: {} }) {
  return {
    "enrich.dossier": enrichDossier(config),
    "source.search": sourceSearch(config),
    "send.draft": sendDraftHandler(config),
    "cadence.user": cadenceUser(config),
    "funnel.reply": funnelReplyHandler(config),
    "outcomes.roll": outcomesRollHandler(),
    hop_evidence: hopEvidenceHandler(config),
    // plan 29 §B2.4: the student's voice
    ...voiceHandlers(config),
    // plan 35 C2: submits the queued Claude requests as one batch and carries on from the answers that came back
    "claude.batch.poll": async (job, ctx) => {
      await ctx.queue.setVt(job.queue, job.msgId, 300);
      const r = await pollClaudeBatches(makeServices(config, { db: ctx.db, now: ctx.now, queue: ctx.queue }));
      console.log(JSON.stringify({ fn: "orbit-worker", step: "claude.batch.poll", ...r }));
    }
  };
}

